import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Walkthrough: Rate limits, wait prompts and the Redis failure fallback","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/rate-limits"},"headers":[],"relativePath":"en/tutorials/rate-limits.md","filePath":"en/tutorials/rate-limits.md"}'),n={name:"en/tutorials/rate-limits.md"};function r(o,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="walkthrough-rate-limits-wait-prompts-and-the-redis-failure-fallback" tabindex="-1">Walkthrough: Rate limits, wait prompts and the Redis failure fallback <a class="header-anchor" href="#walkthrough-rate-limits-wait-prompts-and-the-redis-failure-fallback" aria-label="Permalink to &quot;Walkthrough: Rate limits, wait prompts and the Redis failure fallback&quot;">​</a></h1><p>Run <code>just dev</code> and the API enables three fixed-window policies by default, with a 60-second window. The same direct TCP peer address shares one budget per policy:</p><table tabindex="0"><thead><tr><th>Policy</th><th>Current request</th><th style="text-align:right;">Redis available</th><th style="text-align:right;">Local fallback</th></tr></thead><tbody><tr><td>registration</td><td>POST registration</td><td style="text-align:right;">20</td><td style="text-align:right;">5</td></tr><tr><td>authentication</td><td>Authentication POSTs: sign-in and password reset; not register/logout</td><td style="text-align:right;">60</td><td style="text-align:right;">20</td></tr><tr><td>resource</td><td>Everything else, including reads, resource writes and logout</td><td style="text-align:right;">600</td><td style="text-align:right;">120</td></tr></tbody></table><p><code>/health/live</code> and <code>/health/ready</code> consume no budget, so rate limiting cannot make the process health probes misreport. Requests that are allowed still run the normal Session, API key, CSRF and resource permission checks.</p><h2 id="_1-watch-one-limit-and-its-recovery-on-the-page" tabindex="-1">1. Watch one limit and its recovery on the page <a class="header-anchor" href="#_1-watch-one-limit-and-its-recovery-on-the-page" aria-label="Permalink to &quot;1. Watch one limit and its recovery on the page&quot;">​</a></h2><p>To learn quickly, you can temporarily set these three values in your local <code>.env</code> and restart <code>just dev</code>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">RATE_LIMIT_AUTHENTICATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">RATE_LIMIT_AUTHENTICATION_FALLBACK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">RATE_LIMIT_WINDOW_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3</span></span></code></pre></div><p>Open the sign-in page and submit wrong credentials repeatedly within one window. Once the cap is reached, the response is the unified <code>429</code> with an integer-second <code>Retry-After</code>, a body of <code>rate_limit.exceeded</code>, and <code>error.details.retry_after_seconds</code> repeating the same wait; request_id is still present.</p><p>The registration/sign-in pages keep the input and show a countdown; resubmission is impossible while waiting. When the time is up the button recovers, but no request is sent automatically. Ordinary resource pages show the same wait prompt, and the API/Query layers never retry multiplicatively on their own. After trying it out, restore the default configuration so the learning budget does not affect everyday development.</p><p>A fixed window may admit two batches across adjacent window boundaries; nothing here claims a sliding window or a uniform rate. Tune the production numbers against your deployment size and measurements.</p><h2 id="_2-what-the-redis-counter-and-the-local-counter-each-do" tabindex="-1">2. What the Redis counter and the local counter each do <a class="header-anchor" href="#_2-what-the-redis-counter-and-the-local-counter-each-do" aria-label="Permalink to &quot;2. What the Redis counter and the local counter each do&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/crates/app/src/modules/rate_limit/mod.rs" target="_blank" rel="noreferrer">Core rate-limit module</a> sits in front of the route handlers, picks the policy from the real matched route and HTTP method, then hashes the direct peer address into an internal bucket id. The port does not take part in the id, IPv4-mapped IPv6 is normalized to IPv4, and a client-supplied <code>X-Forwarded-For</code> is never trusted.</p><p>Several users behind the same proxy therefore share the proxy address&#39;s budget. Trusted proxy forwarding requires a deployment-time trust boundary; a header any client can forge must never become an identity. Custom assemblies without TCP context use a shared unknown bucket instead of skipping the protection; the real API executable already passes in <code>ConnectInfo&lt;SocketAddr&gt;</code>.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/crates/platform/src/rate_limit.rs" target="_blank" rel="noreferrer">Redis WindowCounter</a> performs &quot;read the current count → compare against the cap → update with TTL&quot; in a single Lua operation. API instances sharing one Redis namespace, policy and window share the budget; once the cap is reached the remote counter stops increasing. Each operation tries once, with its own concurrency and overall deadlines.</p><p>The local side also records every request, including consumption while Redis is healthy or refusing. When Redis fails, the decision uses this already-consumed window and the lower local cap — switching stores never restores full quota. A timed-out remote command may already have executed, so the local decision is deliberately more conservative and never resends it just to get a &quot;definitive&quot; answer.</p><p>The local map holds at most 4096 peer/policy entries by default, and each new window cleans out expired ones. When capacity is full, new sources share a conservative overflow window per policy; old entries are never evicted to restore quota. A process restart clears local counts; this fallback targets single-machine operation and does not pretend to be a durable cross-machine quota.</p><h2 id="_3-limits-still-apply-when-redis-is-down" tabindex="-1">3. Limits still apply when Redis is down <a class="header-anchor" href="#_3-limits-still-apply-when-redis-is-down" aria-label="Permalink to &quot;3. Limits still apply when Redis is down&quot;">​</a></h2><p>Stop your development Redis:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span></code></pre></div><p>Existing consumption stays in the local window; if you are already past the lower fallback cap you keep receiving <code>429</code>. The next window restores only what the local policy allows. Redis being unavailable never turns identity checks into allow, and never keeps the API from starting.</p><p>Bring Redis back:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span></code></pre></div><p>Later independent requests re-establish the connection and try remote counting again. Cache and rate limiting reuse the same <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/crates/platform/src/redis_transport.rs" target="_blank" rel="noreferrer">private Redis transport</a> connection/timeout implementation, but with separate concurrency capacities — rate limiting never enters the cache&#39;s unbounded retry or queueing.</p><p>The default total budget for a rate-limit Redis operation is 50 ms, covering connection creation, sending and waiting for the reply; at full concurrency capacity the decision falls back to local immediately. Time is composed of the system time at process start plus monotonic elapsed time; tests inject a controllable clock, so a system clock reset never moves a local window backwards.</p><h2 id="_4-configuration-and-observation" tabindex="-1">4. Configuration and observation <a class="header-anchor" href="#_4-configuration-and-observation" aria-label="Permalink to &quot;4. Configuration and observation&quot;">​</a></h2><p>The <a href="./../reference/config">generated configuration reference</a> lists the <code>RATE_LIMIT_*</code> defaults and ranges: the window, the three normal caps, the three fallback caps, the local entry capacity, the Redis namespace and the operation deadline. A fallback cap must be greater than zero and no larger than its normal cap. Format or range errors fail before listening and report only the field name.</p><p>Using Owner/Admin, read from the browser console:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1/system/rate-limits&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p>The result contains only the allow/deny/fallback cumulative counters of the three fixed policies and the local entry total — never raw addresses, bucket hashes, emails, secrets or per-user labels. Request logs keep using route, status and request_id. The metering endpoint itself is protected by the ordinary resource budget.</p><p>The default rate-limit entry point of the runtime configuration is enabled. The base router assembly used for focused HTTP tests starts without it; when assembling the application yourself, provide an explicit instance through <code>CoreOptions.limiter</code>. The standard API executable already uses <code>RateLimiter::from_env</code> — this is not a test-only demonstration.</p><h2 id="_5-the-frontend-and-the-public-contract" tabindex="-1">5. The frontend and the public contract <a class="header-anchor" href="#_5-the-frontend-and-the-public-contract" aria-label="Permalink to &quot;5. The frontend and the public contract&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/crates/app/src/http.rs" target="_blank" rel="noreferrer">unified error factory</a> builds the same <code>429</code> envelope and <code>Retry-After</code>. The final assembled OpenAPI declares that response for every protected operation, so the generated SDK never needs a second error definition per business.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/packages/views/src/system/rate-limit.tsx" target="_blank" rel="noreferrer">shared wait prompt</a> only recognizes the public error code and the 1–3600 second range; arbitrary error text is never treated as an executable hint. The authentication form&#39;s timer starts from the actual request failure and is cleaned up on leaving the page; the countdown only re-enables the button, with no background resend. Business error views compose the same prompt and keep their existing input and error handling. Inline images and attachment links keep their rate-limit errors too and disable retry while waiting; the prompt uses safe inline markup.</p><p>Sign-in/registration success navigation uses a callback that lives as long as the page&#39;s observer, so a late authentication response cannot yank the page back after the user left.</p><h2 id="_6-verification" tabindex="-1">6. Verification <a class="header-anchor" href="#_6-verification" aria-label="Permalink to &quot;6. Verification&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rate_limits</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cached_documents</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/rate-limits.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/registration.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/sessions.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The HTTP tests against real Redis/PostgreSQL use a controllable clock to verify thresholds, shared windows and recovery; a <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/tests/support/redis_gate.rs" target="_blank" rel="noreferrer">shared TCP forwarding fixture</a> disconnects Redis and proves that old consumption still counts and local quota stays limited. Local capacity overflow, the three policies&#39; independence, forged forwarding addresses doing nothing, allowed requests still requiring authentication, the public metering and the generated contract are all verified.</p><p>View tests advance the wait with controlled timers and verify there is no automatic POST, the form input survives, and retry is explicitly possible after the wait. After finishing the whole journey, run the isolated browser profile once:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RATE_LIMIT_AUTHENTICATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RATE_LIMIT_AUTHENTICATION_FALLBACK</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RATE_LIMIT_WINDOW_SECS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">3</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/rate-limits.spec.ts</span></span></code></pre></div><p>Real HTTP requests consume the authentication window, the browser sees the <code>429</code> and the wait button, and once the window recovers a real account signs in. Everyday development keeps using the faster HTTP/view checks.</p><h2 id="_7-extending-with-your-own-business" tabindex="-1">7. Extending with your own business <a class="header-anchor" href="#_7-extending-with-your-own-business" aria-label="Permalink to &quot;7. Extending with your own business&quot;">​</a></h2><p>New ordinary business routes automatically inherit the resource policy and the unified error contract; handlers remain responsible for permissions. When you need a different policy, add a bounded category in Core&#39;s explicit classification and configuration, metered with stable labels — never build metric labels per document, user or URL.</p><p>Rate limiting, configuration, the shared UI prompt, the Redis transport, the authentication tutorial and the matching Core tests survive removing the knowledge base. Your own business never needs a second rate limiter, and Redis never becomes the single source of truth for identity or business facts.</p><hr><p>Source version：<code>0d2db282c3de</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0d2db282c3de303ccd9511beec02540ed6f50600/docs/tutorials/17-rate-limits.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,45)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
